import type { LiveVehicleKind } from './liveMapTypes';

// Auto-generated file containing base64 marker images
export const MARKER_IMAGES = {
  premium_car: "data:image/png;base64,",
  auto: "data:image/png;base64,",
  bike: "data:image/png;base64,",
  car: "data:image/png;base64,"
};

export type MarkerImageKey = keyof typeof MARKER_IMAGES;

/**
 * The backend only ever emits `bike | auto | mini_truck | prime_sedan`
 * (`models/Partner.js`). We only generated three sprites, so the two truck
 * kinds share the car art. `car`/`taxi`/`two-wheeler` are kept as aliases
 * because older payloads and existing `RealMap` callers still use those names.
 */
const MARKER_IMAGE_BY_VEHICLE: Record<LiveVehicleKind, MarkerImageKey> = {
  bike: 'bike',
  auto: 'auto',
  car: 'car',
  premium_car: 'premium_car',
};

const MARKER_IMAGE_ALIASES: Record<string, MarkerImageKey> = {
  prime_sedan: 'premium_car',
  car: 'car',
  taxi: 'car',
  sedan: 'car',
  'two-wheeler': 'bike',
  two_wheeler: 'bike',
  motorcycle: 'bike',
  scooter: 'auto',
  rickshaw: 'auto',
};

/**
 * `vehicleType` -> sprite key. Serialized into the map WebView as a plain
 * lookup table so the page resolves art without re-inlining the base64 sprites
 * under every alias.
 */
export const MARKER_IMAGE_KEYS: Record<string, MarkerImageKey> = {
  ...MARKER_IMAGE_BY_VEHICLE,
  ...MARKER_IMAGE_ALIASES,
};

export function markerImageKeyFor(vehicleType?: string | null): MarkerImageKey {
  if (!vehicleType) return 'car';
  return MARKER_IMAGE_KEYS[vehicleType] ?? MARKER_IMAGE_KEYS[vehicleType.toLowerCase()] ?? 'car';
}

export function markerImageFor(vehicleType?: string | null): string {
  return MARKER_IMAGES[markerImageKeyFor(vehicleType)];
}
